SELECT *
FROM shipment_records
WHERE status <> 'DELIVERED'
  AND COALESCE(last_reconciled_at, updated_at) <= #{updatedBefore}
ORDER BY COALESCE(last_reconciled_at, updated_at), id
LIMIT #{limit}

mapper.insert:

INSERT IGNORE INTO shipment_events(
  shipment_id, event_id, event_type, status, location, description, occurred_at
) VALUES (
  #{shipmentId}, #{eventId}, #{eventType}, #{status}, #{location}, #{description}, #{occurredAt}
)

mapper.select:

SELECT COUNT(*)
FROM shipment_notifications
WHERE notification_id = #{notificationId}

mapper.update:

UPDATE shipment_records
SET last_reconciled_at = CURRENT_TIMESTAMP(6),
    reconciliation_error = #{error}
WHERE id = #{id}
